def solve(path):
    """Simplify an absolute Unix path.
    Resolve '.' and '..' components, collapse multiple slashes, and
    remove any trailing slash (except for the root).
    """
    # Split by '/' and process components
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            # ignore empty and current directory
            continue
        if part == '..':
            if stack:
                stack.pop()
            # If stack empty, stay at root (do nothing)
            continue
        # regular directory name
        stack.append(part)
    # Construct simplified path
    if not stack:
        return '/'  # root
    return '/' + '/'.join(stack)

