def solve(lst):
    """Flatten a nested iterable structure, extracting only integer values.
    The function accepts any iterable (list, tuple, etc.) as input; non‑iterable
    inputs result in an empty list. Strings and bytes are treated as atomic
    values and are not iterated over. Only objects of type int are included in
    the output list, preserving the original order.
    """
    from collections.abc import Iterable
    # Return empty list for non‑iterable inputs (except int which is not iterable)
    if not isinstance(lst, Iterable) or isinstance(lst, (str, bytes, bytearray)):
        return []
    result = []
    def helper(item):
        if isinstance(item, Iterable) and not isinstance(item, (str, bytes, bytearray)):
            for sub in item:
                helper(sub)
        else:
            if isinstance(item, int):
                result.append(item)
    helper(lst)
    return result

