def solve(nested):
    """Flatten an arbitrarily nested list of integers using an iterative stack.
    Only list objects are treated as containers; other types are considered leaf values.
    """
    result = []
    stack = [nested]
    while stack:
        cur = stack.pop()
        if isinstance(cur, list):
            # push in reverse order to preserve left-to-right when popping
            for item in reversed(cur):
                stack.append(item)
        else:
            result.append(cur)
    result.reverse()
    return result

