def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    Supports '+', '-', '*', '/' where division truncates toward zero.
    Uses integer arithmetic without converting through float to avoid overflow.
    """
    stack = []
    for t in tokens:
        # token is an operand if it represents an integer (including negatives)
        if t.lstrip('-').isdigit():
            stack.append(int(t))
            continue
        # Otherwise it must be an operator
        if len(stack) < 2:
            raise ValueError('Insufficient operands')
        b = stack.pop()
        a = stack.pop()
        if t == '+':
            stack.append(a + b)
        elif t == '-':
            stack.append(a - b)
        elif t == '*':
            stack.append(a * b)
        elif t == '/':
            # Truncate toward zero without using float division.
            # Python's // floors toward -inf, so adjust when signs differ.
            if b == 0:
                raise ZeroDivisionError('division by zero')
            q = a // b
            # If a and b have opposite signs and division is not exact, add 1 to correct toward zero.
            if (a ^ b) < 0 and a % b != 0:
                q += 1
            stack.append(q)
        else:
            raise ValueError(f'Unsupported operator: {t}')
    if not stack:
        return 0
    return stack[-1]

