    Only list and tuple objects are treated as containers; all other values are
    considered leaf nodes. Returns a flat list of the integer leaf values in
    left‑to‑right order.
    """
    result = []
    def dfs(item):
        if isinstance(item, (list, tuple)):
            for sub in item:
                dfs(sub)
        else:
            # consider only true ints (bool is subclass of int, exclude it)
            if isinstance(item, int) and not isinstance(item, bool):
                result.append(item)
    dfs(nested)
    return result

