        return 0
    rows = len(grid)
    visited = [[False] * max_cols for _ in range(rows)]
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):  # iterate only existing columns in this row
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                # DFS using stack
                stack = [(i, j)]
                visited[i][j] = True
                while stack:
                    x, y = stack.pop()
                    # explore four directions
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
