def solve(grid):
    """Count number of islands (4-directionally connected 1s) in a grid.
    Handles empty grid and non‑rectangular rows gracefully.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = max((len(r) for r in grid), default=0)
    visited = [[False]*len(grid[i]) for i in range(rows)]
    def dfs(r, c):
        stack = [(r, c)]
