def solve(n,b):
    if b<2 or b>36:
        raise ValueError('Base out of range')
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    if n==0:
        return '0'
    sign = '-' if n<0 else ''
    n=abs(n)
    res=''
    while n>0:
        n, rem = divmod(n,b)
        res = digits[rem] + res
    return sign + res

